LEDGER = (
    "# household, March\n"
    "2024-03-01 salary 2500.00 March pay\n"
    "2024-03-02 groceries -42.50 weekly shop\n"
    "\n"
    "2024-03-05 Rent -900\n"
)
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def run(argv, stdin=None):
    out, err = io.StringIO(), io.StringIO()
    patches = [mock.patch("sys.stdout", out), mock.patch("sys.stderr", err)]
    if stdin is not None:
        raw = stdin if isinstance(stdin, bytes) else stdin.encode("utf-8")
        patches.append(mock.patch("sys.stdin", io.TextIOWrapper(io.BytesIO(raw))))
    for p in patches:
        p.start()
    try:
        code = main(argv)
    finally:
        for p in patches:
            p.stop()
    return code, out.getvalue(), err.getvalue()


class CliCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.path = os.path.join(self.tmp.name, "house.txt")
        self.write(LEDGER)

    def write(self, text, path=None):
        with open(path or self.path, "w", encoding="utf-8", newline="") as f:
            f.write(text)

    def read_bytes(self):
        self.assertEqual((r.returncode, r.stdout), (70, ""))
        self.assertNotIn("Traceback", r.stderr)

    def test_missing_stdin_exit_2(self):
        for cmd in ("balance", "summary", "list", "export"):
            with mock.patch("sys.stdin", None):
                code, out, err = run([cmd, "-"])
            self.assertEqual((code, out), (2, ""), cmd)
            self.assertIn("pennywise: cannot read standard input", err)

    def test_closed_stdin_object_exit_2(self):
        stdin = io.TextIOWrapper(io.BytesIO(b"x"))
        stdin.close()
        with mock.patch("sys.stdin", stdin):
            code, out, err = run(["balance", "-"])
        self.assertEqual((code, out), (2, ""))
        self.assertIn("pennywise: cannot read standard input", err)

    def test_stdout_write_error_exit_2(self):
        class Full(io.StringIO):
            def write(self, text):
    def test_add_wrong_arg_count_exit_2(self):
        self.assertEqual(run(["add", self.path, "2024-01-01", "a"])[0], 2)
        self.assertEqual(run(["add", self.path, "2024-01-01", "a", "1", "n", "extra"])[0], 2)


class Subprocess(CliCase):
    def _run(self, *args, stdin=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        return subprocess.run(
            [sys.executable, "-m", "pennywise", *args],
            input=stdin, capture_output=True, text=True, env=env, cwd=self.tmp.name,
        )

    def test_module_entry_point(self):
        r = self._run("balance", self.path)
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, "1557.50\n", ""))

    def test_exit_codes(self):
        self.assertEqual(self._run().returncode, 2)
        self.write("bad\n")
        r = self._run("balance", self.path)
        self.assertEqual((r.returncode, r.stdout), (1, ""))
        self.assertIn("line 1", r.stderr)

    def _closed_pipe(self, *args, stdin=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        p = subprocess.Popen(
            [sys.executable, "-m", "pennywise", *args],
            stdin=subprocess.PIPE if stdin is not None else None,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, cwd=self.tmp.name,
        )
        p.stdout.close()  # reader goes away before any output is read
        _, err = p.communicate(stdin.encode("utf-8") if stdin is not None else None)
        return p.returncode, err.decode("utf-8", "replace")

    def test_closed_stdout_pipe_is_quiet(self):
        big = "".join("2024-03-01 item%d -1.00 note\n" % i for i in range(20000))
        self.write(big)
        for args in (("list", self.path), ("export", self.path), ("summary", self.path)):
            code, err = self._closed_pipe(*args)
            self.assertEqual((code, err), (141, ""), args)
        code, err = self._closed_pipe("list", "-", stdin=big)
        self.assertEqual((code, err), (141, ""))

    @unittest.skipUnless(os.name == "posix", "needs a POSIX shell")
    def test_closed_stdin_exit_2(self):
        env = dict(os.environ, PYTHONPATH=ROOT)
        r = subprocess.run(
            ["sh", "-c", '"$0" -m pennywise balance - <&-', sys.executable],
            capture_output=True, text=True, env=env, cwd=self.tmp.name,
        )

